head.script:
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.init = function() {
	dataList2.setData(["L1", "V1", "L2", "V2", "L3", "V3"]);
	dataList3.setData(["X1", "A1", "X2", "A2", "X3", "A3"]);
	dataList1.setData(["V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3"]);
	scwin.trigger2_onclick();
}
scwin.gridView1_getType = function(info) {
	var returnInfo = {};
	if ((info.colIndex % 3) === (info.rowIndex % 3)) {
		returnInfo["inputType"] = "select";
		returnInfo["options"] = {
			"viewType": "icon",
			"selectedData": "false"
		};
		if (scwin.Z) {
			returnInfo["itemSet"] = {
				"nodeset": "data:dataList2",
				"label": "col1",
				"value": "col2"
			};
		} else {
			returnInfo["itemSet"] = {
				"nodeset": "data:dataList3",
				"label": "col1",
				"value": "col2"
			};
		}
	} else {
		returnInfo["inputType"] = "textarea";
	}
	returnInfo["id"] = "gridView1_" + returnInfo["inputType"] + "_" + info.rowIndex + "_" + info.colIndex;
	return returnInfo;
}
scwin.trigger1_onclick = function(e) {
	scwin.Z = true;
	dataList1.setData(["V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3", "V1", "V2", "V3", "V2", "V4", "V1", "V2", "V1", "V3"]);
};
scwin.trigger2_onclick = function(e) {
	scwin.Z = false;
	dataList1.setData(["A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3", "A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3", "A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3", "A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3", "A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3", "A1", "A2", "A3", "A2", "A4", "A1", "A2", "A1", "A3"]);
};
scwin.checkVal = function() {
	return scwin.__getDom($p.id+"gridView1_cell_0_0").textContent == 'L1';
}
scwin.checkVal2 = function() {
	return scwin.__getDom($p.id+"gridView1_cell_0_0").textContent == 'X1';
}
scwin.checkVal3 = function() {
	return dataList3.getColData('col1')[0] == scwin.__getDom($p.id+"gridView1_cell_0_0").textContent;
}
scwin.onpageload = function() {
	scwin.Z = true;
	scwin.init();
};
